/// <summary>
/// Extension class of form data source METSalesTable in form SalesTable
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, METSalesTable))]
public final class METSalesTableFormMETSalesTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Write the record
    /// </summary>
    public void write()
    {
        FormDataSource metSalesTableDS = this;
        METSalesTable metSalesTableLocal = metSalesTableDS.cursor();
        SalesTable    salesTableLocal = metSalesTableDS.formRun().dataSource(formDataSourceStr(SalesTable, SalesTable)).cursor();

        salesTableLocal.metPackMETSalesTable(metSalesTableLocal);

        next write();
    }

    /// <summary>
    /// active method on datasource
    /// </summary>
    /// <returns>
    /// int
    /// </returns>
    int active()
    {
        int ret = next active();
        
        this.object(fieldNum(METSalesTable, DeliveryInstructions)).allowEdit(false);

        return ret;
    }
